    "jawapan": [
        {
            "pertanyaan": "Jawapan",
            "jawapan": [
                {
                    "pilihanA": "a",
                    "pilihanB": ["b", "c"],
                    "pilihanC": "",
                    "pilihanD": ""
                }
            ]
        },
        {
